class TrieNode:
    def __init__(self):
        self.children = [None, None]

class Trie:
    BITS = 46  # subtree sums can exceed 2**31

    def __init__(self):
        self.root = TrieNode()

    def insert(self, x):
        node = self.root
        for b in range(self.BITS - 1, -1, -1):
            k = (x >> b) & 1
            if not node.children[k]:
                node.children[k] = TrieNode()
            node = node.children[k]

    def query(self, x):
        # Maximum x ^ y over all inserted y (0 if the Trie is empty)
        node = self.root
        ans = 0
        for b in range(self.BITS - 1, -1, -1):
            k = (x >> b) & 1
            if node.children[1 - k]:
                ans |= (1 << b)
                node = node.children[1 - k]
            elif node.children[k]:
                node = node.children[k]
            else:
                break
        return ans

def maxXor(n, edges, values):
    tree = [[] for _ in range(n)]
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    # Step 1: parents and subtree sums (iterative)
    parent = [-1] * n
    order = []
    stack = [0]
    while stack:
        u = stack.pop()
        order.append(u)
        for v in tree[u]:
            if v != parent[u]:
                parent[v] = u
                stack.append(v)
    subsum = values[:]
    for u in reversed(order):
        if parent[u] != -1:
            subsum[parent[u]] += subsum[u]

    # Step 2: on entering a node, query the Trie of finished subtrees;
    # on leaving it, insert its subtree sum.
    trie = Trie()
    result = 0
    stack = [(0, False)]
    while stack:
        u, done = stack.pop()
        if done:
            trie.insert(subsum[u])
            continue
        result = max(result, trie.query(subsum[u]))
        stack.append((u, True))
        for v in tree[u]:
            if v != parent[u]:
                stack.append((v, False))
    return result
